class Solution {
public:
    vector<vector<int>> modifiedMatrix(vector<vector<int>>& matrix) {
        int m = matrix.size(), n = matrix[0].size();
        vector<int> colMax(n, INT_MIN);
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) colMax[j] = max(colMax[j], matrix[i][j]);
        auto ans = matrix;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (ans[i][j] == -1) ans[i][j] = colMax[j];
        return ans;
    }
};

