class Solution {
    public int[][] modifiedMatrix(int[][] matrix) {
        int m = matrix.length, n = matrix[0].length;
        int[] colMax = new int[n];
        Arrays.fill(colMax, Integer.MIN_VALUE);
        for (int[] row : matrix)
            for (int j = 0; j < n; j++) colMax[j] = Math.max(colMax[j], row[j]);
        int[][] ans = new int[m][];
        for (int i = 0; i < m; i++) {
            ans[i] = matrix[i].clone();
            for (int j = 0; j < n; j++)
                if (ans[i][j] == -1) ans[i][j] = colMax[j];
        }
        return ans;
    }
}

