class Solution {
    public int[][] modifiedMatrix(int[][] matrix) {
        int m = matrix.length, n = matrix[0].length;
        int[] colMax = new int[n];
        List<int[]> holes = new ArrayList<>();
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == -1) holes.add(new int[]{i, j});
                else colMax[j] = Math.max(colMax[j], matrix[i][j]);
            }
        for (int[] h : holes) matrix[h[0]][h[1]] = colMax[h[1]];
        return matrix;
    }
}

